method correct_bracketing(brackets: string) returns (result: bool)
    requires brackets != null
    ensures result == (CountOpening(brackets) == CountClosing(brackets))

    // Helper functions to count opening and closing brackets
    method CountOpening(s: string) returns (count: int)
        requires s != null
        ensures count >= 0
        decreases s.Length
    {
        if s.Length == 0 then
            return 0;
        else if s[0] == '<' then
            return 1 + CountOpening(s[1..]);
        else
            return CountOpening(s[1..]);
    }

    method CountClosing(s: string) returns (count: int)
        requires s != null
        ensures count >= 0
        decreases s.Length
    {
        if s.Length == 0 then
            return 0;
        else if s[0] == '>' then
            return 1 + CountClosing(s[1..]);
        else
            return CountClosing(s[1..]);
    }
```

